import ast, sys
src = open(sys.argv[1]).read()
tree = ast.parse(src)
# Check for expiry pattern near Counter
has_counter = 'Counter' in src
has_expiry = any(s in src for s in ['[-', 'maxlen', 'expire', '[-N', 'runs >=', 'tail', '[-10'])
if has_counter and not has_expiry:
    print('R115 FAIL: Counter() used with no expiry slice — history grows unbounded'); sys.exit(1)
# Check for unused imports via ast
imports = set()
for node in ast.walk(tree):
    if isinstance(node, ast.Import):
        for a in node.names: imports.add(a.asname or a.name.split('.')[0])
    if isinstance(node, ast.ImportFrom):
        for a in node.names: imports.add(a.asname or a.name)
used = set(re.findall(r'\\b([a-zA-Z_][a-zA-Z0-9_]*)\\b', src))
dead = imports - used - {'__main__'}
if dead:
    print(f'R115 WARN: dead imports: {dead}')
print('R115 PASS')
